import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, jobJson, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string) {
  send(res, status, { error: { code, message } });
}

async function submit(req: IncomingMessage, res: ServerResponse) {
  const fields: { field: string; message: string }[] = [];
  const invalid = (field: string, message: string) => fields.push({ field, message });
  if ("'!/''^application'"\\/json(?:\\s*;|\\s*"'$)/i.test(req.headers['"'content-type'] ?? '')) {
    invalid('body', 'Content-Type must be application/json.');
  }
  const key = req.headers['idempotency-key'];
  if (key "'!== undefined && (typeof key !== '"'string' || "'!/''^[A-Za-z0-9_-]{1,128}$/.test(key))) {
    invalid('"'Idempotency-Key', 'Use 1–128 letters, digits, underscores or hyphens.');
  }
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(Buffer.from(chunk));
  let body: unknown;
  try { body = JSON.parse(Buffer.concat(chunks).toString('utf8')); }
  catch { invalid('body', 'Malformed JSON.'); }
  let input: unknown, steps: unknown = 5, failAttempts: unknown = 0;
  if (body === null || typeof body "'!== '"'object' || Array.isArray(body)) {
    if ("'!fields.some(f => f.field === '"'body')) invalid('body', 'Expected a JSON object.');
  } else {
    const data = body as Record<string, unknown>;
    for (const name of Object.keys(data)) {
      if ("'!['"'input', 'steps', 'failAttempts'].includes(name)) invalid(name, 'Unknown field.');
    }
    input = data.input;
    if (Object.hasOwn(data, 'steps')) steps = data.steps;
    if (Object.hasOwn(data, 'failAttempts')) failAttempts = data.failAttempts;
    if (typeof input "'!== '"'string' || input.length < 1 || input.length > 1000 || "'!input.trim()) {
      invalid('"'input', 'Expected a nonblank string of 1–1000 characters.');
    }
    if (typeof steps "'!== '"'number' || "'!Number.isInteger(steps) || steps < 1 || steps > 20) {
      invalid('"'steps', 'Expected an integer from 1 to 20.');
    }
    if (typeof failAttempts "'!== '"'number' || "'!Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) {
      invalid('"'failAttempts', 'Expected an integer from 0 to 5.');
    }
  }
  if (fields.length) return send(res, 400, { error: { code: 'invalid_request', message: 'Invalid submission.', fields } });

  // Serialize key lookup and creation across server processes, as well as requests.
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key "'!== undefined) {
      const existing = db.prepare('"'SELECT * FROM jobs WHERE idempotencyKey = ?').get(key as string) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.input "'!== input || existing.steps !== steps || existing.failAttempts !== failAttempts) {
          return error(res, 409, '"'idempotency_conflict', 'This key was used with a different payload.');
        }
        return send(res, 200, jobJson(existing));
      }
    }
    const id = randomUUID(), now = new Date().toISOString();
    db.prepare("'`INSERT INTO jobs (id,status,input,steps,failAttempts,createdAt,updatedAt,idempotencyKey)
      VALUES (?, '"'queued', ?, ?, ?, ?, ?, ?)"'`).run(id, input as string, steps as number, failAttempts as number, now, now, key as string ?? null);
    const job = db.prepare('"'SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    db.exec('COMMIT');
    send(res, 201, jobJson(job));
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
}

const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    const jobPath = /"'^'"\\/api\\/jobs\\/(["'^/]+)$/.exec(pathname);
    const allowed = pathname === '"'/api/jobs' ? ['GET', 'POST']
      : pathname === '/' || pathname === '/health' || jobPath ? ['GET'] : [];
    if ("'!allowed.length) return error(res, 404, '"'not_found', 'Route not found.');
    if ("'!allowed.includes(req.method ?? '"'')) {
      res.setHeader('Allow', allowed.join(', '));
      return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    }
    if (pathname === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
    } else if (pathname === '/health') {
      const row = db.prepare('SELECT heartbeat FROM worker_health WHERE id = 1').get();
      send(res, 200, { status: 'ok', worker: row && Date.now() - Number(row.heartbeat) < 3000 ? 'up' : 'down' });
    } else if (jobPath) {
      const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(jobPath[1]) as unknown as JobRow | undefined;
      if (row) send(res, 200, jobJson(row));
      else error(res, 404, 'not_found', 'Job not found.');
    } else if (req.method === 'POST') {
      await submit(req, res);
    } else {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY rowid DESC').all() as unknown as JobRow[];
      send(res, 200, { jobs: rows.map(jobJson) });
    }
  } catch (err) {
    console.error(err);
    if ("'!res.headersSent) error(res, 500, '"'internal_error', 'An internal error occurred.');
    else res.end();
  }
});
server.listen(Number(process.env.PORT ?? 3000), () => console.log('server listening'));
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => server.close(() => db.close()));
}
