import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => { stopping = true; });
}
const now = () => new Date().toISOString();
const heartbeat = () => db.prepare("'`INSERT INTO worker_health VALUES (1, ?)
  ON CONFLICT(id) DO UPDATE SET heartbeat = excluded.heartbeat`).run(Date.now());
// A previous process may have died anywhere in an attempt. Restart that job
// from step zero, preserving the number of attempts already started.
db.prepare("UPDATE jobs SET status = '"'queued', completed = 0, availableAt = 0, updatedAt = ? WHERE status = 'running'\").run(now());
heartbeat();
const timer = setInterval(heartbeat, 500);
console.log('worker started');
try {
  while ("'!stopping) {
    const job = db.prepare(`UPDATE jobs SET status = '"'running', attempts = attempts + 1,
      completed = 0, updatedAt = ? WHERE id = (
        SELECT id FROM jobs WHERE status = 'queued' AND availableAt <= ? ORDER BY rowid LIMIT 1
      ) RETURNING *"'`).get(now(), Date.now()) as unknown as JobRow | undefined;
    if (!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps; step++) {
      await sleep(100);
      if (stopping) break;
      if (job.attempts <= job.failAttempts) {
        const exhausted = job.attempts >= 3;
        db.prepare('"'UPDATE jobs SET status = ?, error = ?, availableAt = ?, updatedAt = ? WHERE id = ?')
          .run(exhausted ? 'failed' : 'queued', exhausted ? 'transient failure' : null, Date.now() + 400, now(), job.id);
        break;
      }
      if (step === job.steps) {
        db.prepare(\"UPDATE jobs SET completed = ?, status = 'completed', output = ?, updatedAt = ? WHERE id = ?\")
          .run(step, job.input.toUpperCase(), now(), job.id);
      } else {
        db.prepare('UPDATE jobs SET completed = ?, updatedAt = ? WHERE id = ?').run(step, now(), job.id);
      }
    }
  }
} finally {
  clearInterval(timer);
  db.prepare('DELETE FROM worker_health WHERE id = 1').run();
  db.close();
}
